import argparse
import csv
import json
from collections import Counter

def main():
    parser = argparse.ArgumentParser(description="Profile a UTF-8 CSV without altering the source.")
    parser.add_argument("csv_file")
    parser.add_argument("--key", help="Column checked for blank and duplicate values")
    args = parser.parse_args()
    with open(args.csv_file, encoding="utf-8-sig", newline="") as source:
        reader = csv.reader(source, strict=True)
        columns = next(reader, [])
        if not columns or len(set(columns)) != len(columns) or not all(columns):
            parser.error("the first row must contain unique, non-empty column names")
        if args.key and args.key not in columns:
            parser.error("--key must match an existing column")
        key_index = columns.index(args.key) if args.key else None
        blanks = Counter()
        keys = Counter()
        total = 0
        skipped = 0
        for row in reader:
            total += 1
            if len(row) != len(columns):
                skipped += 1
                continue
            for column, value in zip(columns, row):
                if not value.strip():
                    blanks[column] += 1
            if key_index is not None and row[key_index].strip():
                keys[row[key_index]] += 1
    print(json.dumps({
        "rows": total,
        "wrong_width_rows": skipped,
        "blank_cells_by_column": {column: blanks[column] for column in columns},
        "key": args.key,
        "duplicate_key_rows": sum(count - 1 for count in keys.values()),
    }, ensure_ascii=False))

if __name__ == "__main__":
    try:
        main()
    except (OSError, UnicodeError, csv.Error) as error:
        raise SystemExit(str(error)) from error

